const MANIFEST = "{\n  \"name\": \"Wormstar Sentinel Workspace\",\n  \"short_name\": \"Wormstar\",\n  \"description\": \"Responsive defensive cybersecurity workspace\",\n  \"start_url\": \"./\",\n  \"display\": \"standalone\",\n  \"background_color\": \"#0a101d\",\n  \"theme_color\": \"#0a101d\",\n  \"lang\": \"ar\",\n  \"dir\": \"rtl\",\n  \"icons\": []\n}";
const SW = "const CACHE = \"wormstar-sentinel-ui-v1\";\nconst CORE = [\"./\", \"./index.html\", \"./manifest.webmanifest\"];\nself.addEventListener(\"install\", event => {\n  event.waitUntil(caches.open(CACHE).then(cache => cache.addAll(CORE)).then(() => self.skipWaiting()));\n});\nself.addEventListener(\"activate\", event => {\n  event.waitUntil(caches.keys().then(keys => Promise.all(keys.filter(key => key !== CACHE).map(key => caches.delete(key)))).then(() => self.clients.claim()));\n});\nself.addEventListener(\"fetch\", event => {\n  const request = event.request;\n  if (request.method !== \"GET\" || new URL(request.url).origin !== self.location.origin) return;\n  event.respondWith(caches.match(request).then(cached => cached || fetch(request).then(response => {\n    if (response.ok && response.type === \"basic\") {\n      const copy = response.clone();\n      caches.open(CACHE).then(cache => cache.put(request, copy));\n    }\n    return response;\n  }).catch(() => caches.match(\"./index.html\"))));\n});";

function response(body, type, status = 200) {
  return new Response(body, {
    status,
    headers: {
      "Content-Type": type,
      "Cache-Control": "no-store",
      "X-Content-Type-Options": "nosniff",
      "X-Frame-Options": "DENY",
      "Referrer-Policy": "strict-origin-when-cross-origin",
      "Permissions-Policy": "camera=(), microphone=(), geolocation=()",
      "Content-Security-Policy": "default-src 'self'; base-uri 'self'; object-src 'none'; frame-ancestors 'none'; img-src 'self' data:; style-src 'self' 'unsafe-inline' https://fonts.googleapis.com; font-src 'self' https://fonts.gstatic.com data:; script-src 'self' 'unsafe-inline'; connect-src 'self'"
    }
  });
}

export default {
  async fetch(request) {
    if (request.method !== "GET" && request.method !== "HEAD") {
      return response("Method not allowed", "text/plain; charset=utf-8", 405);
    }
    const path = new URL(request.url).pathname;
    if (path === "/" || path === "/index.html") {
      return response(request.method === "HEAD" ? null : INDEX, "text/html; charset=utf-8");
    }
    if (path === "/manifest.webmanifest") {
      return response(request.method === "HEAD" ? null : MANIFEST, "application/manifest+json; charset=utf-8");
    }
    if (path === "/sw.js") {
      return response(request.method === "HEAD" ? null : SW, "text/javascript; charset=utf-8");
    }
    return response("Not found", "text/plain; charset=utf-8", 404);
  }
};